{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text_1",
        "title_h2",
        "intro_text_2",
        "divider_1",
        "sales_data_card"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Monthly Sales Performance Overview",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text_1": {
      "type": "Text",
      "props": {
        "text": "This section presents the provided monthly sales data, structured for generating a bar chart.",
        "variant": "body"
      },
      "children": []
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Monthly Sales Data for Visualization",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text_2": {
      "type": "Text",
      "props": {
        "text": "Below is the sales data for the specified months. This data is suitable for a bar chart where the Month represents the X-axis and Sales represents the Y-axis.",
        "variant": "body"
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "sales_data_card": {
      "type": "Card",
      "props": {},
      "children": [
        "sales_table"
      ]
    },
    "sales_table": {
      "type": "Table",
      "props": {
        "domain": "generic",
        "preferredPresentation": "table",
        "columns": [
          {
            "key": "Month",
            "label": "Month"
          },
          {
            "key": "Sales",
            "label": "Sales"
          }
        ],
        "rows": [
          {
            "Month": "Jan",
            "Sales": 150
          },
          {
            "Month": "Feb",
            "Sales": 180
          },
          {
            "Month": "Mar",
            "Sales": 160
          }
        ]
      },
      "children": []
    }
  }
}
